import * as Plot from "@observablehq/plot";
import { type BarChartOptions, type BarPoint, barModel, labelFits } from "../render/bar-model.js";
import { keyed, renderPlot } from "../render/plot.js";

export type { BarChartOptions } from "../render/bar-model.js";

/**
 * A bar chart, drawn on the server: one series, or several stacked or grouped. Negative values
 * stack below zero. Each bar carries hover details and, once enhanced, filters by its series (or
 * its category when there is one series).
 *
 * @example
 * barChart({
 *   data: [{ year: 2023, type: "Publications" }, { year: 2024, type: "Talks" }],
 *   x: "year",
 *   series: "type",
 *   alt: "Entries per year by type, 2023 to 2024.",
 * });
 */
export function barChart<T extends object>(options: BarChartOptions<T>): string {
  const model = barModel(options);
  const { points, xNames, seriesNames, horizontal, grouped, thinned, categoryLabel } = model;

  const render = keyed(
    points,
    model.datum,
    // A link is read on its own, so it carries its own name.
    options.href ? (el, p) => el.setAttribute("aria-label", model.describe(p)) : undefined,
  );

  const link = model.link;
  const common = {
    fill: "series",
    title: model.describe,
    render,
    ...(link ? { href: (p: BarPoint) => link(p) } : {}),
  };
  const order = { order: [...seriesNames] };
  let bar: Plot.Markish;
  if (horizontal) {
    bar = grouped
      ? Plot.barX(points, { ...common, x: "value", y: "series", fy: "x" })
      : Plot.barX(points, Plot.stackX({ ...common, ...order, x: "value", y: "x" }));
  } else {
    bar = grouped
      ? Plot.barY(points, { ...common, y: "value", x: "series", fx: "x" })
      : Plot.barY(points, Plot.stackY({ ...common, ...order, y: "value", x: "x" }));
  }

  const categoryScale = {
    domain: grouped ? seriesNames : xNames,
    label: grouped ? null : categoryLabel,
    padding: grouped ? 0.05 : 0.2,
    ...(grouped ? { axis: null } : thinned ? { ticks: thinned } : {}),
  };
  const facetScale = {
    domain: xNames,
    label: categoryLabel,
    padding: 0.15,
    axis: horizontal ? "left" : "bottom",
    ...(thinned ? { ticks: thinned } : {}),
  } as const;
  const ticks = model.countTicks;
  const valueScale = {
    label: model.valueLabel,
    labelArrow: "none",
    labelAnchor: "center",
    grid: true,
    zero: true,
    // Counts are whole numbers, so their axis never shows 0.5, and the axis ends at the last
    // tick so no tick is drawn past the plot (A2).
    ...(ticks
      ? {
          ticks,
          tickFormat: model.format,
          domain: [0, ticks[ticks.length - 1] ?? 1],
          nice: false,
        }
      : { nice: true }),
  } as const;

  const { svg } = renderPlot(
    {
      width: model.width,
      height: model.height,
      marginTop: 20,
      marginLeft: model.marginLeft,
      marginBottom: 44,
      ...(horizontal
        ? {
            y: { ...categoryScale, type: "band" },
            x: valueScale,
            ...(grouped ? { fy: facetScale } : {}),
          }
        : {
            x: { ...categoryScale, type: "band" },
            y: valueScale,
            ...(grouped ? { fx: facetScale } : {}),
          }),
      color: { domain: seriesNames, range: [...model.plan.range] },
      marks: [bar, horizontal ? Plot.ruleX([0]) : Plot.ruleY([0])],
    },
    options.alt,
    options.href ? "group" : "img",
    model.directLabels ? (svg) => labelSegments(svg) : undefined,
  );

  return model.figure(svg);
}

/**
 * Writes each series' name inside the stacked segments it fits in, in the color chosen for text
 * on that series. Drawn after Plot lays out the bars, from their final geometry.
 */
function labelSegments(svg: SVGSVGElement): void {
  const group = svg.querySelector('[data-enarratio-mark="bar"]');
  if (!group) return;
  const document = svg.ownerDocument;
  const labels = document.createElementNS("http://www.w3.org/2000/svg", "g");
  labels.setAttribute("data-enarratio-mark", "bar label");
  labels.setAttribute("aria-hidden", "true");
  // Labels sit on the bars they name; pointer events go through them to the bar.
  labels.setAttribute("pointer-events", "none");
  labels.setAttribute("text-anchor", "middle");
  labels.setAttribute("font-size", "11");
  for (const mark of group.querySelectorAll("[data-enarratio-key]")) {
    const shape = mark.localName === "rect" ? mark : mark.querySelector("rect");
    const name = mark.getAttribute("data-enarratio-series");
    const fill = shape?.getAttribute("fill") ?? "";
    const slot = /--enarratio-series-(\d)/.exec(fill)?.[1];
    if (!shape || !name || !slot) continue;
    const [bx, by, bw, bh] = ["x", "y", "width", "height"].map((a) =>
      Number(shape.getAttribute(a)),
    ) as [number, number, number, number];
    if (!labelFits(name, bw, bh)) continue;
    const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
    text.setAttribute("x", String(bx + bw / 2));
    text.setAttribute("y", String(by + bh / 2));
    text.setAttribute("dy", "0.35em");
    text.setAttribute("fill", `var(--enarratio-series-text-${slot})`);
    text.textContent = name;
    labels.append(text);
  }
  group.after(labels);
}

src/plot/heatmap.ts.source:
import * as Plot from "@observablehq/plot";
import {
  defaultFormat,
  domainOf,
  type KeysOfType,
  markKey,
  maxOf,
  minOf,
  rampStep,
  rampThresholds,
  readCategory,
  readNumberOrNull,
} from "../render/data.js";
import { type FigureOptions, figure, type RampItem, validateFigure } from "../render/figure.js";
import { decorate, keyed, renderPlot } from "../render/plot.js";
import { DEFAULT_WIDTH } from "../render/size.js";

/** Options for {@link heatmap}. */
export interface HeatmapOptions<T extends object> extends FigureOptions {
  readonly data: readonly T[];
  /** The column field. */
  readonly x: KeysOfType<T, string | number>;
  /** The row field. */
  readonly y: KeysOfType<T, string | number>;
  /** The field colored by the theme's sequential ramp. `null` is an empty cell, outlined dashed. */
  readonly value: KeysOfType<T, number | null | undefined>;
  readonly xDomain?: readonly (string | number)[];
  readonly yDomain?: readonly (string | number)[];
  /**
   * Four ascending thresholds splitting values into the ramp's five steps. Defaults to equal
   * intervals between the lowest and highest value.
   */
  readonly thresholds?: readonly [number, number, number, number];
  /** Print each value in its cell (default true when there are 100 cells or fewer). */
  readonly cellLabels?: boolean;
  readonly xLabel?: string | null;
  readonly yLabel?: string | null;
  /** What the value measures, for hover details and the table header. */
  readonly valueLabel?: string;
  readonly formatValue?: (value: number) => string;
}

interface Cell {
  readonly x: string;
  readonly y: string;
  readonly value: number | null;
  readonly step: number;
}

const KIND = "heatmap";

/**
 * A grid of cells colored by value on the theme's sequential ramp: cohort retention, weekly
 * activity, plate layouts. Colors come in five labeled steps, printed values keep the chart
 * readable without color, and empty cells are outlined with a dashed line rather than colored as zero.
 *
 * @example
 * heatmap({ data: cohorts, x: "month", y: "cohort", value: "retained", alt: "..." });
 */
export function heatmap<T extends object>(options: HeatmapOptions<T>): string {
  const { data, x, y, value } = options;
  validateFigure(KIND, options);
  if (data.length === 0) throw new Error(`${KIND}: data is empty`);
  const format = options.formatValue ?? defaultFormat;
  const valueLabel = options.valueLabel ?? value;
  const xs = data.map((row, i) => readCategory(KIND, row, x, i));
  const ys = data.map((row, i) => readCategory(KIND, row, y, i));
  const xNames = domainOf(KIND, x, xs, options.xDomain);
  const yNames = domainOf(KIND, y, ys, options.yDomain);
  const values = data.map((row, i) => readNumberOrNull(KIND, row, value, i));
  const present = values.filter((v): v is number => v !== null);
  if (present.length === 0) throw new Error(`${KIND}: every value is empty`);

  const seen = new Set<string>();
  data.forEach((_, i) => {
    const id = `${xs[i]}|${ys[i]}`;
    if (seen.has(id)) throw new Error(`${KIND}: two rows for cell ${xs[i]}, ${ys[i]}`);
    seen.add(id);
  });

  const min = minOf(present);
  const max = maxOf(present);
  const thresholds = rampThresholds(KIND, min, max, options.thresholds);
  const cells = data.map((_, i): Cell => {
    const v = values[i] ?? null;
    return {
      x: String(xs[i]),
      y: String(ys[i]),
      value: v,
      step: v === null ? 0 : rampStep(v, thresholds),
    };
  });

  const filledCells = cells.filter((c) => c.value !== null);
  const emptyCells = cells.filter((c) => c.value === null);
  const xColumn = options.xLabel ?? x;
  const yColumn = options.yLabel ?? y;
  const describe = (c: Cell): string =>
    `${yColumn} ${c.y}, ${xColumn} ${c.x}: ${c.value === null ? "no data" : `${format(c.value)} ${valueLabel}`}`;
  const showLabels = options.cellLabels ?? cells.length <= 100;

  const longest = Math.max(maxOf(yNames.map((n) => n.length)), 1);
  const marks: Plot.Markish[] = [
    Plot.cell(emptyCells, {
      x: "x",
      y: "y",
      fill: "none",
      stroke: "var(--enarratio-status-unknown)",
      strokeDasharray: "3,2",
      inset: 1.5,
      title: describe,
    }),
    Plot.cell(filledCells, {
      x: "x",
      y: "y",
      inset: 1,
      title: describe,
      render: keyed(
        filledCells,
        (c) => ({
          key: markKey(c.x, c.y),
          filter: { field: y, value: c.y },
          x: c.x,
          column: xNames.indexOf(c.x),
          row: yNames.indexOf(c.y),
        }),
        (el, c) => el.setAttribute("fill", `var(--enarratio-sequential-${c.step})`),
      ),
    }),
  ];
  if (showLabels) {
    marks.push(
      Plot.text(filledCells, {
        x: "x",
        y: "y",
        text: (c: Cell) => (c.value === null ? "" : format(c.value)),
        render: decorate(filledCells, (el, c) =>
          el.setAttribute("fill", `var(--enarratio-sequential-text-${c.step})`),
        ),
      }),
    );
  }

  const { svg } = renderPlot(
    {
      width: options.width ?? DEFAULT_WIDTH,
      height: options.height ?? Math.max(160, yNames.length * 32 + 64),
      marginTop: 20,
      marginLeft: Math.min(200, longest * 7 + 24) + (options.yLabel === null ? 0 : 20),
      marginBottom: 44,
      x: {
        type: "band",
        domain: xNames,
        label: options.xLabel === undefined ? x : options.xLabel,
        labelAnchor: "center",
        labelArrow: "none",
      },
      y: {
        type: "band",
        domain: yNames,
        label: options.yLabel === undefined ? y : options.yLabel,
        labelAnchor: "center",
        labelArrow: "none",
      },
      marks,
    },
    options.alt,
  );

  const edges = [min, ...thresholds, max];
  const ramp: RampItem[] = [1, 2, 3, 4, 5].map((step) => ({
    step,
    label:
      step === 1
        ? `below ${format(edges[1] as number)}`
        : step === 5
          ? `${format(edges[4] as number)} or more`
          : `${format(edges[step - 1] as number)} to ${format(edges[step] as number)}`,
  }));
  const cellOf = new Map(cells.map((c) => [`${c.x}|${c.y}`, c]));

  return figure(options, {
    kind: "heatmap",
    svg,
    ramp,
    table: {
      columns: [`${yColumn} \\ ${xColumn}`, ...xNames],
      rows: yNames.map((yn) => [
        yn,
        ...xNames.map((xn) => {
          const c = cellOf.get(`${xn}|${yn}`);
          return c?.value === null || c === undefined ? "" : format(c.value);
        }),
      ]),
    },
  });
}

